@extends('layouts.storefront')
@section('title','Your Cart | MEETA')
@push('styles')<style>.cart-page{padding-top:55px}.cart-page h1{font-size:43px;margin-bottom:5px}.sub{color:var(--muted)}.cart-grid{display:grid;grid-template-columns:1.8fr .8fr;gap:34px;margin-top:35px}.cart-item{display:grid;grid-template-columns:150px 1fr auto;gap:20px;border:1px solid var(--line);padding:18px;margin-bottom:18px;background:#fff}.cart-item img{width:150px;height:145px;object-fit:cover}.cart-item h3{font-size:21px;margin:5px 0}.artisan{color:var(--brown)}.qty{display:inline-flex;background:#f1e7e1;margin-top:20px}.qty button,.qty span{border:0;background:transparent;padding:7px 12px}.minor{border:0;background:none;color:var(--muted);font-size:12px;margin:20px 10px 0 0;cursor:pointer}.remove-item{display:inline-flex;align-items:center;gap:6px;border:1px solid #d9aaa0;background:#fff;color:#a6382f;border-radius:5px;padding:8px 11px;margin-top:16px;cursor:pointer;font-size:12px;font-weight:600}.remove-item svg{width:15px;height:15px}.remove-item:hover{background:#fff1ee;border-color:#a6382f}.remove-item:disabled{opacity:.55;cursor:wait}.line-price{font-size:20px}.summary{border:1px solid var(--line);padding:25px;background:#fff;position:sticky;top:105px;height:max-content}.row{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #eee}.total{font-size:22px;color:var(--brown)}.checkout{width:100%;margin-top:20px}.empty{text-align:center;padding:100px 20px}.empty h2{font-size:34px}@media(max-width:800px){.cart-grid{grid-template-columns:1fr}.cart-item{grid-template-columns:100px 1fr}.cart-item img{width:100px;height:110px}.line-price{grid-column:2}.summary{position:static}}</style>@endpush
@section('content')<main class="cart-page wrap"><h1>Your Curated Selection</h1><p class="sub">Each piece supports an artisan's lifelong journey.</p><div id="cart"><div class="loading">Loading your selection…</div></div></main>@endsection
@push('scripts')<script>
if(!protectPage())throw new Error('Authentication required');
async function loadCart(){try{const {data}=await api('/api/customer/cart');setCartCount(data.items_count||0);if(!data.items.length){document.getElementById('cart').innerHTML=`<div class="empty"><h2>Your cart is waiting for a story.</h2><p>Explore pieces made slowly, thoughtfully and by hand.</p><a class="btn primary" href="/categories">Explore Crafts</a></div>`;return}document.getElementById('cart').innerHTML=`<div class="cart-grid"><div>${data.items.map(i=>`<article class="cart-item"><img src="${i.product.image}" alt="${i.product.name}"><div><h3>${i.product.name}</h3><div class="artisan">By ${i.product.artisan||'MEETA Artisan'}</div><div class="qty"><button data-action="dec" data-id="${i.id}" data-qty="${i.quantity}" aria-label="Decrease quantity">−</button><span>${i.quantity}</span><button data-action="inc" data-id="${i.id}" data-qty="${i.quantity}" data-max="${i.variant.available_quantity}" aria-label="Increase quantity">+</button></div><br><button class="minor" data-action="wish" data-id="${i.id}">♡ MOVE TO WISHLIST</button><button class="remove-item" data-action="remove" data-id="${i.id}" aria-label="Remove ${i.product.name} from cart"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14M10 10v6m4-6v6"/></svg><span>Remove</span></button></div><div class="line-price">₹${Number(i.line_total).toLocaleString('en-IN')}</div></article>`).join('')}</div><aside class="summary"><h2>Order Summary</h2><div class="row"><span>Items (${data.items_count})</span><span>₹${Number(data.subtotal).toLocaleString('en-IN')}</span></div><div class="row"><span>Shipping</span><span>Calculated at checkout</span></div><div class="row total"><strong>Subtotal</strong><strong>₹${Number(data.subtotal).toLocaleString('en-IN')}</strong></div><a class="btn primary checkout" href="/checkout">Proceed to Checkout →</a><p style="text-align:center;font-size:12px;color:var(--muted)">Secure checkout · Authenticity assured</p></aside></div>`;bindCart()}catch(e){toast(e.message)}}
function bindCart(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{const a=b.dataset.action,id=b.dataset.id;b.disabled=true;if(a==='remove')await api('/api/customer/cart/items/'+id,{method:'DELETE'});else if(a==='wish')await api('/api/customer/cart/items/'+id+'/move-to-wishlist',{method:'POST'});else{const qty=Number(b.dataset.qty)+(a==='inc'?1:-1);if(qty<1){b.disabled=false;return}if(a==='inc'&&qty>Number(b.dataset.max))throw Error('Maximum available stock reached');await api('/api/customer/cart/items/'+id,{method:'PATCH',body:JSON.stringify({quantity:qty})})}await loadCart()}catch(e){b.disabled=false;toast(e.message)}})}loadCart();
</script>@endpush
